const COMMON_SKILLS = ['git-github','dsa','leetcode'];
function normalizeBranch(value='') {
  const raw=String(value||'').toLowerCase().replace(/&/g,' and ').replace(/[–—]/g,'-');
  if (!raw.trim()) return 'CSE';
  if ((raw.includes('cse')||raw.includes('computer science')) && /(ai|machine learning|aiml|ml)/.test(raw)) return 'CSE (AI/ML)';
  if (raw.includes('artificial intelligence') || raw.includes('ai and data') || raw.includes('data science') || raw==='ai & data science') return 'AI & Data Science';
  if (raw.includes('information technology') || raw==='it') return 'IT';
  if (raw.includes('computer science') || raw==='cse' || raw.includes('b.tech cse')) return 'CSE';
  for (const [value,label] of BRANCH_OPTIONS) if(raw===value.toLowerCase()||raw===label.toLowerCase()||raw.includes(label.toLowerCase())) return value;
  if (raw.includes('electrical')||raw==='eee') return 'EEE';
  if (raw.includes('electronics')||raw==='ece') return 'ECE';
  if (raw.includes('mechanical')) return 'Mechanical';
  if (raw.includes('civil')) return 'Civil';
  if (raw.includes('chemical')) return 'Chemical';
  if (raw.includes('biomedical')) return 'Biomedical';
  if (raw.includes('biotech')) return 'Biotechnology';
  if (raw.includes('aerospace')||raw.includes('aeronautical')) return 'Aerospace';
  if (raw.includes('automobile')||raw.includes('automotive')) return 'Automobile';
  if (raw.includes('agricultural')||raw.includes('agriculture')) return 'Agricultural';
  if (raw.includes('mining')) return 'Mining';
  if (raw.includes('industrial')||raw.includes('production')) return 'Industrial / Production';
  if (raw.includes('environmental')) return 'Environmental';
  return 'Other / Custom';
}
function branchConfig(value=state.profile?.branch){const key=normalizeBranch(value);return {key,label:BRANCH_OPTIONS.find(x=>x[0]===key)?.[1]||key,...(BRANCH_RECOMMENDATIONS[key]||BRANCH_RECOMMENDATIONS['Other / Custom'])};}
function branchSelectOptions(value){const selected=normalizeBranch(value);return BRANCH_OPTIONS.map(([v,label])=>`<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(label)}</option>`).join('');}
function branchMatchesCatalog(item){const cfg=branchConfig();if(cfg.key==='Other / Custom')return true;const id=item[0];if(item[4]==='Role')return cfg.roles.includes(id);return cfg.skills.includes(id)||COMMON_SKILLS.includes(id);}
function branchRecommendedItems(items){return [...items].sort((a,b)=>Number(branchMatchesCatalog(b))-Number(branchMatchesCatalog(a)));}
function roleOptionList(branch,current){const cfg=branchConfig(branch);return [...ROLE_CATALOG].sort((a,b)=>Number(cfg.roles.includes(b[0]))-Number(cfg.roles.includes(a[0]))).map(r=>`<option value="${esc(r[1])}" ${current===r[1]?'selected':''}>${cfg.key!=='Other / Custom'&&cfg.roles.includes(r[0])?'★ Recommended · ':''}${esc(r[1])}</option>`).join('');}
function branchPicker(id, branch, compact=false){const cfg=branchConfig(branch);return `<label class="branch-picker ${compact?'branch-picker-compact':''}" for="${esc(id)}"><span class="branch-picker-label">${compact?'YOUR BRANCH':'ENGINEERING BRANCH'}</span><select id="${esc(id)}" aria-label="Engineering branch">${branchSelectOptions(branch)}</select><span class="branch-picker-note">${esc(cfg.summary)}</span></label>`;}


