for (const [slug, phases] of Object.entries(ROLE_CURRICULUM_DATA)) {
  CURRICULUM_BLUEPRINTS[slug] = phases.map(([title, summary, effort, project, moduleA, moduleB, topics]) => {
    const names = String(topics).split('|').map(x => x.trim()).filter(Boolean);
    const midpoint = Math.ceil(names.length / 2);
    return {title, summary, effort, project, groups:[[moduleA, names.slice(0, midpoint)],[moduleB, names.slice(midpoint)]]};
  });
}

