for (const [slug, phases] of Object.entries(DOMAIN_CURRICULUM_DATA)) {
  CURRICULUM_BLUEPRINTS[slug] = phases.map(([title,summary,effort,project,moduleA,moduleB,topics]) => {
    const names=String(topics).split('|').map(x=>x.trim()).filter(Boolean); const midpoint=Math.ceil(names.length/2);
    return {title,summary,effort,project,groups:[[moduleA,names.slice(0,midpoint)],[moduleB,names.slice(midpoint)]]};
  });
}

function makeStages(slug, title) {
  const titleCase = title || slug.replace(/-/g, ' ');
  const aliasSlug = (!CURRICULUM_BLUEPRINTS[slug] && !STAGE_SETS[slug]) ? CURRICULUM_ALIASES[slug] : null;
  const blueprint = CURRICULUM_BLUEPRINTS[slug] || (aliasSlug ? CURRICULUM_BLUEPRINTS[aliasSlug] : null);
  if (blueprint) {
    return blueprint.map((raw, stageIndex) => {
      const allTopicNames = raw.groups.flatMap(group => group[1]);
      let globalTopicIndex = 0;
      const topics = raw.groups.flatMap((group, moduleIndex) => group[1].map((name, topicIndex) => {
        const currentIndex = globalTopicIndex++;
        const previous = currentIndex > 0 ? allTopicNames[currentIndex - 1] : '';
        const resources = getTopicLearningResources(slug, titleCase, name);
        return {
          id: `${slug}-${stageIndex}-${moduleIndex}-${topicIndex}`,
          name,
          module: group[0],
          sourceModuleIndex: moduleIndex,
          detail: describeTopic(name, group[0], titleCase),
          prerequisite: currentIndex === 0 ? 'No specialist prerequisite. Review the overview, then start with the basics.' : `Recommended sequence: first understand “${previous}”; revisit earlier foundations if this concept feels unfamiliar.`,
          effort: name.length > 52 ? '1–2 hours' : '45–90 minutes',
          practice: buildPracticeTask(name, titleCase),
          criterion: buildCompletionCriterion(name),
          resources,
          resource: resources[0] || chooseLearningResource(slug, titleCase)
        };
      }));
      return {title:raw.title,summary:raw.summary,effort:raw.effort,project:raw.project,topics,stageIndex};
    });
  }
  const source = STAGE_SETS[slug] || (aliasSlug ? STAGE_SETS[aliasSlug] : null);
  const genericStages = [
    ['Foundations', `Understand the core ideas behind ${titleCase}.`, `Core concepts and terminology`, `Tools and environment setup`, `Small exercises and debugging`, `Build a foundations mini-project`],
    ['Practical fundamentals', `Practice common workflows in ${titleCase}.`, `Common workflows and patterns`, `Data, interfaces or integrations`, `Testing and error handling`, `Build a guided practical project`],
    ['Applied skills', `Apply intermediate techniques to realistic situations.`, `Intermediate patterns and trade-offs`, `Use cases and real-world constraints`, `Documentation and quality checks`, `Create a portfolio-ready project`],
    ['Quality and delivery', `Make your work reliable, explainable and shippable.`, `Review fundamentals and weak areas`, `Explain design choices and limitations`, `Publish work and prepare for interviews`, `Publish a documented project and demo`]
  ];
  const rawStages = source || genericStages;
  const stages = rawStages.map((raw, stageIndex) => {
    const modulePhrases = raw.slice(2, 5);
    const topics = modulePhrases.flatMap((phrase, moduleIndex) => {
      const leafNames = splitIntoSubtopics(phrase, slug, titleCase);
      return leafNames.map((leafName, leafIndex) => {
        const fullName = normalizeTopicName(leafName, titleCase, phrase);
        const detail = describeTopic(fullName, phrase, titleCase);
        const sourceLink = chooseLearningResource(slug, titleCase);
        return {
          id: `${slug}-${stageIndex}-${moduleIndex}-${leafIndex}`,
          name: fullName,
          module: phrase,
          sourceModuleIndex: moduleIndex,
          detail,
          prerequisite: stageIndex === 0 && moduleIndex === 0 && leafIndex === 0
            ? 'No specialist prerequisite; start with the basics and note what you already know.'
            : moduleIndex > 0 && leafIndex === 0
              ? `First review the earlier topic group: ${modulePhrases[moduleIndex - 1]}.`
              : leafIndex > 0
                ? `Build on the earlier subtopic in “${phrase}”.`
                : `Review the previous phase, “${rawStages[stageIndex - 1]?.[0] || 'Foundations'}”, if it feels unfamiliar.`,
          effort: leafIndex === 0 ? '1–2 hours' : '45–90 min',
          practice: buildPracticeTask(fullName, titleCase),
          criterion: buildCompletionCriterion(fullName),
          resource: sourceLink,
          sourceModuleIndex: moduleIndex
        };
      });
    });
    return {
      title: raw[0],
      summary: raw[1],
      topics,
      project: raw[5] || `Build a practical ${titleCase} mini-project`,
      effort: ['1–2 weeks', '2–3 weeks', '2–4 weeks', '2–3 weeks'][stageIndex],
      stageIndex
    };
  });
  stages.push({
    title: 'Capstone & Career Readiness',
    summary: `Combine the skills from ${titleCase} into evidence you can demonstrate, document and discuss in interviews.`,
    effort: '2–4 weeks',
    stageIndex: 4,
    project: `Create and publish a ${titleCase} capstone with a clear README, demo and reflection.`,
    topics: [
      ['Define a real problem and scope', 'Translate a specific user need into a small, testable project.', 'Choose one realistic problem, write user stories, define out-of-scope work and split the work into milestones.'],
      ['Plan architecture and data flow', 'Describe how the main parts communicate before coding.', 'Sketch the components, data model, key flows and likely failure cases in a short design note.'],
      ['Build a working vertical slice', 'Implement one end-to-end feature before adding polish.', 'Ship a minimal path through the app or project that can be used from start to finish.'],
      ['Test edge cases and accessibility', 'Check behavior beyond the happy path.', 'Create a small test checklist covering invalid inputs, empty states, errors, keyboard use and responsive layouts.'],
      ['Debug and review the implementation', 'Use evidence rather than guessing when something fails.', 'Record a bug, reproduce it, isolate its cause, fix it and add a regression check.'],
      ['Document and publish your project', 'Make it easy for another person to understand and run.', 'Write a README with problem, features, setup, screenshots/demo, limitations and future work; publish only secrets-free code.'],
      ['Prepare a project walkthrough', 'Explain decisions and trade-offs clearly.', 'Prepare a two-minute walkthrough covering the problem, architecture, hardest bug, tests and what you would improve.'],
      ['Review interview and portfolio gaps', 'Turn remaining weak areas into the next learning cycle.', 'Update your portfolio truthfully and select three topics to revisit based on the questions you struggled to explain.']
    ].map((row, j) => ({
      id: `${slug}-4-capstone-${j}`,
      name: row[0], module: 'Capstone workflow', sourceModuleIndex: j,
      detail: row[1], prerequisite: j === 0 ? `Complete or intentionally skip the earlier ${titleCase} phases before starting the capstone.` : 'Complete the previous capstone workflow item first.',
      effort: j < 2 ? '1–2 hours' : '2–4 hours', practice: row[2],
      criterion: buildCompletionCriterion(row[0]),
      resource: chooseLearningResource(slug, titleCase)
    }))
  });
  return stages;
}

function splitIntoSubtopics(phrase, slug, title) {
  const clean = String(phrase || '').replace(/[()]/g, ' ').replace(/\s+/g, ' ').trim();
  const explicit = {
    'variables, data types, operators and conversions': ['Variables, identifiers and scope', 'Primitive and reference data types', 'Operators, expressions and precedence', 'Type conversion and casting'],
    'conditionals, loops and methods': ['Conditional statements and boolean logic', 'Loop selection, counters and termination', 'Method parameters, return values and reuse'],
    'arrays, strings and command-line input': ['Array creation, indexing and traversal', 'String operations and immutability', 'Command-line arguments and input validation'],
    'classes, interfaces, inheritance and exceptions': ['Classes, objects, constructors and encapsulation', 'Interfaces and abstraction', 'Inheritance, overriding and polymorphism', 'Exception handling and custom errors'],
    'collections, generics and basic complexity': ['List, Set and Map selection', 'Generics, type safety and iterators', 'Time complexity and operation trade-offs'],
    'spring boot project structure and dependency injection': ['Spring Boot project structure and configuration', 'Dependency injection and bean lifecycle', 'Profiles and application properties'],
    'controllers, services, repositories and dtos': ['Controller responsibilities and request mapping', 'Service layer and business logic', 'Repository layer and persistence', 'DTOs and request/response boundaries'],
    'react components, props and state': ['Component composition and JSX', 'Props, data flow and reusable interfaces', 'State, events and rerendering'],
    'effects, forms, routing and reusable hooks': ['Effects and external synchronization', 'Controlled forms and validation', 'Client-side routing and layouts', 'Custom hooks and shared behavior'],
    'train/validation/test splits and leakage': ['Training, validation and test splits', 'Data leakage and how it distorts evaluation', 'Reproducible split strategy'],
    'sql, relational modeling and joins': ['Relational tables and schema design', 'Primary keys, foreign keys and relationships', 'JOIN types and correct join keys'],
    'authentication and authorization concepts': ['Authentication: proving who the user is', 'Authorization: checking what an identity may do', 'Session handling and access-control tests'],
    'testing, logging and secure configuration': ['Unit and integration testing', 'Useful, privacy-aware logging', 'Environment configuration and secret management'],
    'git branches, commits and pull requests': ['Small, meaningful commits', 'Branches and merge conflict resolution', 'Pull requests, review and collaboration'],
    'responsive and keyboard testing': ['Small-screen and responsive testing', 'Keyboard navigation and visible focus', 'Contrast, semantics and accessibility checks']
  };
  const normalized = clean.toLowerCase();
  if (explicit[normalized]) return explicit[normalized];
  let pieces = clean.split(/,|\s+and\s+|\s+or\s+|\s*\/\s*|;|\s*&\s*/i).map(s => s.trim()).filter(Boolean);
  pieces = pieces.map(s => s.replace(/^and\s+/i, '').replace(/^or\s+/i, '').trim()).filter(s => s.length > 1);
  // Keep wording meaningful and avoid making a one-word skill look like a whole curriculum.
  if (pieces.length === 1) {
    const seed = pieces[0];
    pieces = [`${seed} concepts and terminology`, `${seed} workflows and common patterns`, `${seed} debugging, edge cases and quality checks`];
  } else if (pieces.length === 2) {
    pieces.push(`Hands-on practice with ${pieces[0].toLowerCase()} and ${pieces[1].toLowerCase()}`);
  }
  return pieces.slice(0, 5);
}

function normalizeTopicName(name, title, module) {
  const raw = String(name || '').replace(/^\s+|\s+$/g, '').replace(/\s+/g, ' ');
  const aliases = {
    html: 'HTML semantics and page structure', css: 'CSS selectors, cascade and layout', javascript: 'JavaScript language fundamentals',
    java: 'Java language fundamentals', python: 'Python language fundamentals', sql: 'SQL query fundamentals', react: 'React component fundamentals',
    'git': 'Git fundamentals and version history', 'testing': 'Testing and verification', 'tools': 'Development tools and setup',
    'debugging': 'Debugging and problem isolation', 'deployment': 'Deployment fundamentals', 'documentation': 'Technical documentation'
  };
  const value = aliases[raw.toLowerCase()] || raw.charAt(0).toUpperCase() + raw.slice(1);
  return value.length < 5 ? `${title} — ${value} essentials` : value;
}

function describeTopic(topic, module, title) {
  const s = topic.toLowerCase();
  if (s.includes('variable') || s.includes('data type') || s.includes('scope')) return 'Understand how values are represented, named, stored and passed through the language; note common type or scope mistakes.';
  if (s.includes('operator') || s.includes('expression') || s.includes('conversion') || s.includes('casting')) return 'Practice evaluating expressions, precedence and type conversions, including boundary cases that can change the result.';
  if (s.includes('loop') || s.includes('conditional') || s.includes('boolean')) return 'Choose control flow deliberately, trace it with sample inputs and check termination, branching and boundary conditions.';
  if (s.includes('array') || s.includes('list') || s.includes('set') || s.includes('map') || s.includes('collection')) return 'Learn the structure, common operations, iteration patterns and trade-offs; test empty, duplicate and missing-value cases.';
  if (s.includes('string')) return 'Practice creating, comparing, transforming and validating text; review immutability, encoding or formatting pitfalls where relevant.';
  if (s.includes('class') || s.includes('object') || s.includes('interface') || s.includes('inheritance') || s.includes('polymorphism') || s.includes('encapsulation')) return 'Connect the concept to a small model, identify its responsibilities and explain how it supports reusable, maintainable design.';
  if (s.includes('exception') || s.includes('error handling') || s.includes('error')) return 'Handle expected failures explicitly, preserve useful context, validate input and avoid hiding errors behind generic messages.';
  if (s.includes('api') || s.includes('http') || s.includes('rest') || s.includes('controller') || s.includes('endpoint')) return 'Understand request/response shape, validation, status codes and error formats; test normal, invalid and unauthorized requests.';
  if (s.includes('sql') || s.includes('database') || s.includes('query') || s.includes('join') || s.includes('schema') || s.includes('transaction')) return 'Practice with a small relational dataset and verify correctness, null handling, duplicates, relationships and data integrity.';
  if (s.includes('test') || s.includes('verification')) return 'Create repeatable checks for expected behavior, boundary cases and failures; use the result to guide fixes rather than relying only on a happy-path demo.';
  if (s.includes('security') || s.includes('authorization') || s.includes('authentication') || s.includes('threat') || s.includes('privacy')) return 'Use a defensive mindset: identify trust boundaries, validate inputs, apply least privilege and test both allowed and denied behavior in a safe environment.';
  if (s.includes('data') || s.includes('statistics') || s.includes('metric') || s.includes('analysis') || s.includes('model')) return 'Work through a small example, state assumptions, inspect edge cases and explain what the result does—and does not—support.';
  if (s.includes('deploy') || s.includes('cloud') || s.includes('container') || s.includes('monitor')) return 'Practice a repeatable setup, document configuration, check logs and health, and identify how to roll back a failed change.';
  return `Study ${topic.toLowerCase()} in the context of ${title}. Understand the core idea, build a small example, inspect common failure cases and record your own explanation.`;
}

function buildPracticeTask(topic, title) {
  const s = topic.toLowerCase();
  if (s.includes('array') || s.includes('list') || s.includes('map') || s.includes('collection')) return `Write a small program that uses ${topic.toLowerCase()} to solve one realistic task; test empty input and an edge case.`;
  if (s.includes('sql') || s.includes('join') || s.includes('query') || s.includes('database')) return `Create or use a tiny sample dataset, write three queries for ${topic.toLowerCase()}, and explain the output.`;
  if (s.includes('api') || s.includes('http') || s.includes('endpoint')) return `Design or call one small endpoint, then test a valid request, invalid input and a missing/unauthorized case.`;
  if (s.includes('class') || s.includes('object') || s.includes('interface')) return `Model one real-world entity in code, write a tiny usage example and explain the responsibility of each part.`;
  if (s.includes('test') || s.includes('debug')) return `Create a reproducible test case for ${topic.toLowerCase()}, trigger one failure, fix it and keep the test as a regression check.`;
  return `Complete one small exercise involving ${topic.toLowerCase()}; save the example, explain the result in your own words and test a boundary case.`;
}

function buildCompletionCriterion(topic) {
  return `You can explain ${topic.toLowerCase()} without copying notes, complete one fresh practice task, and identify at least one common mistake or trade-off.`;
}

function chooseLearningResource(slug, title) {
  const s = `${slug} ${title}`.toLowerCase();
  if (/java|spring|kotlin|android|jvm/.test(s)) return {title:'Official Java / Spring documentation',url:/spring|backend|full-stack/.test(s)?'https://spring.io/guides':'https://docs.oracle.com/en/java/'};
  if (/html|css|javascript|frontend|react|typescript|node|web|next-js/.test(s)) return {title:'MDN Web Docs',url:'https://developer.mozilla.org/'};
  if (/python|data|machine|ai|ml|pandas|science|analytics|power-bi/.test(s)) return {title:'Official Python docs and Kaggle Learn',url:/python/.test(s)?'https://docs.python.org/3/tutorial/':'https://www.kaggle.com/learn'};
  if (/sql|postgres|mongo|database|redis|graphql/.test(s)) return {title:'SQLBolt / database documentation',url:/sql|postgres/.test(s)?'https://sqlbolt.com/':'https://www.mongodb.com/docs/'};
  if (/dsa|algorithm|leetcode|software-engineer|programming/.test(s)) return {title:'GeeksforGeeks and LeetCode practice',url:'https://www.geeksforgeeks.org/'};
  if (/cyber|security|devsecops|api-security|red-team/.test(s)) return {title:'OWASP security references',url:'https://cheatsheetseries.owasp.org/'};
  if (/devops|cloud|aws|docker|kubernetes|terraform|linux|network/.test(s)) return {title:'Official cloud and tooling documentation',url:/aws|cloud/.test(s)?'https://skillbuilder.aws/':'https://docs.docker.com/'};
  return {title:'Roadmap.sh + GeeksforGeeks reference',url:'https://roadmap.sh/'};
}

