const ENGINEERING_DOMAIN_SLUGS = new Set(['electronics-fundamentals','embedded-systems','vlsi-design','matlab-simulink','power-systems','cad-mechanical','thermodynamics','robotics','manufacturing-quality','civil-autocad-bim','structural-engineering','chemical-process-engineering','biotechnology-fundamentals','biomedical-instrumentation','aerospace-fundamentals','automotive-engineering','agricultural-engineering','mining-engineering','environmental-engineering','operations-research']);
function getTopicLearningResources(slug, title, topic) {
  const topicText = String(topic || title || '').trim();
  const searchText = `${title} ${topicText}`.trim();
  const domainSlug=ENGINEERING_DOMAIN_SLUGS.has(slug)?slug:CURRICULUM_ALIASES[slug];
  if (domainSlug && ENGINEERING_DOMAIN_SLUGS.has(domainSlug)) {
    const query=encodeURIComponent(`${title} ${topicText} engineering lecture`);
    const links=[
      {source:'YouTube · Engineering lectures',label:'Search video lectures for this topic',url:`https://www.youtube.com/results?search_query=${query}`,type:'video search'},
      {source:'NPTEL',label:'Browse engineering courses and lecture material',url:'https://nptel.ac.in/courses',type:'course catalogue'}
    ];
    if (['embedded-systems','vlsi-design','electronics-fundamentals'].includes(domainSlug)) links.push({source:'GeeksforGeeks',label:'Find related electronics and programming explainers',url:`https://www.geeksforgeeks.org/?s=${encodeURIComponent(searchText)}`,type:'article search'});
    return links.filter(link=>safeUrl(link.url));
  }
  const q = encodeURIComponent(`Apna College ${searchText}`);
  const gfgQ = encodeURIComponent(`${searchText}`);
  const links = [
    {source:'Apna College · YouTube',label:'Search videos for this topic',url:`https://www.youtube.com/results?search_query=${q}`,type:'video search'},
    {source:'GeeksforGeeks',label:'Find topic explanations and examples',url:`https://www.geeksforgeeks.org/?s=${gfgQ}`,type:'article search'}
  ];
  let w3Urls = W3SCHOOLS_TUTORIALS[slug] || [];
  if (!w3Urls.length) {
    const s = `${slug} ${title} ${topicText}`.toLowerCase();
    if (/html|semantic|markup|form|accessibility/.test(s)) w3Urls = ['https://www.w3schools.com/html/'];
    else if (/css|flexbox|grid|responsive|style|animation/.test(s)) w3Urls = ['https://www.w3schools.com/css/'];
    else if (/javascript|dom|promise|async|browser api/.test(s)) w3Urls = ['https://www.w3schools.com/js/'];
    else if (/sql|database|query|join/.test(s)) w3Urls = ['https://www.w3schools.com/sql/'];
    else if (/python|pandas/.test(s)) w3Urls = ['https://www.w3schools.com/python/'];
    else if (/java|jvm|collections/.test(s)) w3Urls = ['https://www.w3schools.com/java/'];
    else if (/c programming|pointer|memory allocation/.test(s)) w3Urls = ['https://www.w3schools.com/c/'];
    else if (/c\+\+|stl|template/.test(s)) w3Urls = ['https://www.w3schools.com/cpp/'];
    else if (/react|component|jsx/.test(s)) w3Urls = ['https://www.w3schools.com/react/'];
  }
  w3Urls.forEach(url => {
    const route = url.split('/').filter(Boolean).slice(-1)[0] || 'tutorial';
    links.push({source:'W3Schools',label:`Open ${route.toUpperCase()} tutorial`,url,type:'tutorial'});
  });
  return links.filter(link => safeUrl(link.url));
}
