function freshState(){return {auth:{loggedIn:false,email:''},profile:null,roadmaps:{},projects:{},activity:{},resume:{fullName:'',headline:'',email:'',phone:'',location:'',summary:'',education:'',skills:'',projects:'',certifications:'',template:'classic'},savedOpportunities:[],applications:{},chat:[],settings:{compact:false},lastUpdated:null};}
function loadState(){try{const parsed=JSON.parse(localStorage.getItem(APP_KEY)||'null');if(!parsed||typeof parsed!=='object')return freshState();const base=freshState();return {...base,...parsed,auth:{...base.auth,...parsed.auth},resume:{...base.resume,...parsed.resume},settings:{...base.settings,...parsed.settings},roadmaps:parsed.roadmaps||{},projects:parsed.projects||{},activity:parsed.activity||{},applications:parsed.applications||{},savedOpportunities:parsed.savedOpportunities||[],chat:parsed.chat||[]};}catch(error){console.warn('DishaSetu storage could not be read; using a clean session.',error);return freshState();}}
const SUPABASE_CONFIG = window.DISHASETU_SUPABASE_CONFIG || {};
const SUPABASE_URL = String(SUPABASE_CONFIG.url || '').trim();
const SUPABASE_PUBLISHABLE_KEY = String(SUPABASE_CONFIG.publishableKey || '').trim();
const SUPABASE_CONFIGURED = /^https:\/\//i.test(SUPABASE_URL) && SUPABASE_URL.includes('.supabase.co') && SUPABASE_PUBLISHABLE_KEY.length > 20 && !/YOUR_PROJECT|YOUR_SUPABASE|PASTE_/i.test(SUPABASE_URL + SUPABASE_PUBLISHABLE_KEY);
let supabaseClient = null;
try { if (SUPABASE_CONFIGURED && window.supabase?.createClient) supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } }); } catch (error) { console.error('Supabase client could not be initialized.', error); }
const SUPABASE_READY = Boolean(supabaseClient);
const localBootstrapState = loadState();
const legacyLocalState = localBootstrapState?.auth?.loggedIn && localBootstrapState?.profile ? JSON.parse(JSON.stringify(localBootstrapState)) : null;
let legacyMigrationAttempted = false;
let state=SUPABASE_CONFIGURED?freshState():localBootstrapState;let toastTimer=null;let catalogFilter='All';let catalogSearch='';let catalogScope='recommended';let skillsSearch='';let skillsCategory='All';let skillsScope='recommended';let roadmapTopicQuery='';let roadmapStatusFilter='all';let selectedRoadmap='';let selectedStageIndex=null;let projectFilter='All';let jdAnalysis=null;
let cloudSession=null, cloudUserId=null, cloudHydratedUserId=null, cloudSyncTimer=null, cloudHydrationRun=0, cloudErrorNotified=false, supabaseBootComplete=!SUPABASE_READY;
function saveState(){state.lastUpdated=new Date().toISOString();try{localStorage.setItem(APP_KEY,JSON.stringify(state));}catch(error){console.error(error);notify('Browser storage is full. Export your data and remove some stored items.');}scheduleCloudSync();}
function notify(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function supabaseRedirectUrl(){return `${window.location.origin}${window.location.pathname}`;}
function normalizeStoredAppState(value,email,fullName=''){
  const base=freshState(); const incoming=value&&typeof value==='object'?value:{};
  const merged={...base,...incoming,auth:{loggedIn:true,email:email||incoming.auth?.email||''},resume:{...base.resume,...incoming.resume},settings:{...base.settings,...incoming.settings},roadmaps:incoming.roadmaps&&typeof incoming.roadmaps==='object'?incoming.roadmaps:{},projects:incoming.projects&&typeof incoming.projects==='object'?incoming.projects:{},activity:incoming.activity&&typeof incoming.activity==='object'?incoming.activity:{},applications:incoming.applications&&typeof incoming.applications==='object'?incoming.applications:{},savedOpportunities:Array.isArray(incoming.savedOpportunities)?incoming.savedOpportunities:[],chat:Array.isArray(incoming.chat)?incoming.chat:[]};
  if(!merged.profile||typeof merged.profile!=='object')merged.profile=null;
  if(!merged.profile&&fullName)merged.pendingName=fullName;
  return merged;
}
function cacheCloudState(){try{localStorage.setItem(APP_KEY,JSON.stringify(state));}catch(error){console.warn('Could not cache cloud state locally.',error);}}
function scheduleCloudSync(){if(!SUPABASE_READY||!cloudSession?.user?.id||cloudHydratedUserId!==cloudSession.user.id)return;clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>{void writeCloudState();},650);}
async function writeCloudState(){
  if(!SUPABASE_READY||!cloudSession?.user?.id||cloudHydratedUserId!==cloudSession.user.id)return;
  const userId=cloudSession.user.id, email=cloudSession.user.email||state.auth.email||'';
  const snapshot=JSON.parse(JSON.stringify(state)); snapshot.auth={loggedIn:true,email}; delete snapshot.pendingName;
  try{
    const stateResult=await supabaseClient.from('user_app_state').upsert({user_id:userId,data:snapshot,updated_at:new Date().toISOString()},{onConflict:'user_id'});
    if(stateResult.error)throw stateResult.error;
    if(state.profile){
      const profilePayload={id:userId,email,full_name:String(state.profile.fullName||''),college:String(state.profile.college||''),branch:String(state.profile.branch||''),year:Math.min(4,Math.max(1,Number(state.profile.year)||1)),graduation_year:Number(state.profile.graduationYear||0)||null,career:String(state.profile.career||''),skills:String(state.profile.skills||''),updated_at:new Date().toISOString()};
      const profileResult=await supabaseClient.from('profiles').upsert(profilePayload,{onConflict:'id'});
      if(profileResult.error)throw profileResult.error;
    }
    cloudErrorNotified=false;
  }catch(error){console.error('DishaSetu cloud save failed:',error);if(!cloudErrorNotified){cloudErrorNotified=true;notify('Cloud save failed. Check that supabase-schema.sql was run and Row Level Security policies are enabled. Your current changes remain in this browser.');}}
}
async function hydrateSupabaseSession(session){
  if(!SUPABASE_READY||!session?.user?.id)return;
  const userId=session.user.id,email=session.user.email||'',fullName=session.user.user_metadata?.full_name||session.user.user_metadata?.name||'';
  if(cloudHydratedUserId===userId&&state.auth.loggedIn){cloudSession=session;state.auth={loggedIn:true,email};return;}
  const run=++cloudHydrationRun;cloudSession=session;cloudUserId=userId;cloudHydratedUserId=null;
  let cloudData=null,profileRow=null;
  try{
    const stateQuery=await supabaseClient.from('user_app_state').select('data').eq('user_id',userId).maybeSingle();
    if(stateQuery.error)throw stateQuery.error;
    cloudData=stateQuery.data?.data||null;
    const profileQuery=await supabaseClient.from('profiles').select('*').eq('id',userId).maybeSingle();
    if(profileQuery.error)throw profileQuery.error;
    profileRow=profileQuery.data||null;
  }catch(error){
    if(run!==cloudHydrationRun)return;
    console.error('Supabase data load failed:',error);
    state=normalizeStoredAppState(null,email,fullName);cacheCloudState();
    cloudHydratedUserId=userId;render();
    if(!cloudErrorNotified){cloudErrorNotified=true;notify('Supabase sign-in worked, but data tables could not be read. Run supabase-schema.sql in the Supabase SQL Editor.');}
    return;
  }
  if(run!==cloudHydrationRun)return;
  if(cloudData){state=normalizeStoredAppState(cloudData,email,fullName);}
  else{
    let migrated=false;
    const localMatches=legacyLocalState&&String(legacyLocalState.auth?.email||'').toLowerCase()===String(email).toLowerCase()&&legacyLocalState.profile;
    if(localMatches&&!legacyMigrationAttempted){legacyMigrationAttempted=true;migrated=confirm('DishaSetu found earlier local demo data for this same email. Import that profile and learning progress into your new cloud account? Choose Cancel to start fresh.');}
    if(migrated){state=normalizeStoredAppState(legacyLocalState,email,fullName);}
    else{state=normalizeStoredAppState(null,email,fullName);if(profileRow?.branch){state.profile={fullName:profileRow.full_name||fullName,email,college:profileRow.college||'',branch:profileRow.branch,year:Number(profileRow.year||1),graduationYear:profileRow.graduation_year||'',career:profileRow.career||'',skills:profileRow.skills||'',dailyHours:2,learningMode:'balanced',experience:''};delete state.pendingName;}}
  }
  state.auth={loggedIn:true,email};cloudSession=session;cloudUserId=userId;cloudHydratedUserId=userId;cacheCloudState();
  const routeNow=routeParts().route;const knownRoutes=['dashboard','roadmaps','skills','roadmap','career','projects','internships','resume','analyzer','activity','mentor','resources','settings','profile','onboarding','login','signup','reset-password'];if(!location.hash||!knownRoutes.includes(routeNow)||['login','signup'].includes(routeNow))navigate(state.profile?'dashboard':'onboarding',true);render();
  if(!cloudData) scheduleCloudSync();
}
function handleSupabaseSignedOut(){cloudHydrationRun++;cloudSession=null;cloudUserId=null;cloudHydratedUserId=null;clearTimeout(cloudSyncTimer);state=freshState();try{localStorage.removeItem(APP_KEY);}catch{}if(routeParts().route!=='login')navigate('login',true);render();}
async function bootstrapSupabase(){
  if(!SUPABASE_READY){if(SUPABASE_CONFIGURED)notify('Supabase is configured but its JavaScript client did not load. Check your internet connection and reload.');if(!location.hash)history.replaceState(null,'','#login');render();return;}
  $('#app').innerHTML='<div class="supabase-boot-screen"><div class="supabase-boot-mark">DS</div><h2>Connecting to DishaSetu</h2><p>Restoring your secure session…</p><div class="supabase-boot-track"><span></span></div></div>';
  const {data,error}=await supabaseClient.auth.getSession();
  supabaseBootComplete=true;
  if(error)console.warn('Supabase session restore:',error.message);
  if(data?.session)await hydrateSupabaseSession(data.session);
  else{state=freshState();try{localStorage.removeItem(APP_KEY);}catch{}if(!location.hash||!['login','signup','reset-password'].includes(routeParts().route))history.replaceState(null,'','#login');render();}
  supabaseClient.auth.onAuthStateChange((event,session)=>{
    window.setTimeout(()=>{
      if(event==='SIGNED_OUT'){handleSupabaseSignedOut();return;}
      if(event==='PASSWORD_RECOVERY'&&session){void hydrateSupabaseSession(session).then(()=>{navigate('reset-password',true);render();});return;}
      if(session?.user)void hydrateSupabaseSession(session);
    },0);
  });
}
async function submitSupabaseAuth(form,mode){
  if(!SUPABASE_READY){notify('Supabase is not configured. Add your project URL and publishable key to supabase-config.js.');return;}
  const email=$('#authEmail')?.value.trim().toLowerCase(),password=$('#authPassword')?.value;
  if(!email||!password){notify('Enter your email and password.');return;}
  if(mode==='signup'&&password.length<8){notify('Use at least 8 characters for your password.');return;}
  const submitButton=form.querySelector('[type="submit"]');if(submitButton){submitButton.disabled=true;submitButton.textContent=mode==='signup'?'Creating account…':'Signing in…';}
  try{
    let result;
    if(mode==='signup')result=await supabaseClient.auth.signUp({email,password,options:{data:{full_name:$('#authName')?.value.trim()||''},emailRedirectTo:supabaseRedirectUrl()}});
    else result=await supabaseClient.auth.signInWithPassword({email,password});
    if(result.error)throw result.error;
    if(mode==='signup'&&!result.data?.session){notify('Account created. Check your email to verify it, then return here to sign in.');navigate('login',true);render();return;}
    if(result.data?.session){await hydrateSupabaseSession(result.data.session);notify(mode==='signup'?'Account created successfully.':'Welcome back!');}
    else if(mode==='login')notify('Sign-in did not return an active session. Check your email verification and try again.');
  }catch(error){console.error('Supabase authentication error:',error);notify(error?.message||'Authentication failed. Please try again.');}
  finally{const current=$('#authForm [type="submit"]');if(current){current.disabled=false;current.innerHTML=(mode==='signup'?'Create account':'Sign in')+' <span>↗</span>';}}
}
async function startGoogleSignIn(){if(!SUPABASE_READY){notify('Configure Supabase before enabling Google sign-in.');return;}try{const {error}=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:supabaseRedirectUrl()}});if(error)throw error;}catch(error){console.error(error);notify(error?.message||'Google sign-in could not start. Check your Google provider settings in Supabase.');}}
async function sendPasswordReset(){if(!SUPABASE_READY){notify('Configure Supabase before using password reset.');return;}const email=$('#authEmail')?.value.trim().toLowerCase();if(!email){notify('Enter your email address first, then choose Forgot password.');$('#authEmail')?.focus();return;}try{const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:supabaseRedirectUrl()+'#reset-password'});if(error)throw error;notify('Password reset email sent. Follow the secure link in your inbox.');}catch(error){console.error(error);notify(error?.message||'Could not send the reset email.');}}
async function submitNewPassword(form){const password=$('#newPassword')?.value||'';if(password.length<8){notify('Use at least 8 characters for your new password.');return;}try{const {error}=await supabaseClient.auth.updateUser({password});if(error)throw error;notify('Password updated successfully.');navigate(state.profile?'dashboard':'onboarding',true);render();}catch(error){console.error(error);notify(error?.message||'Could not update password. Open the latest reset email and try again.');}}
function iconMark(){return '<span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 15.5Q12 4 21 15.5M5.5 15.5v3M18.5 15.5v3M12 21V8" stroke="#050607" stroke-width="1.8" stroke-linecap="round"/><path d="M12 2 13.4 5.1 16.5 6.5 13.4 7.9 12 11 10.6 7.9 7.5 6.5 10.6 5.1Z" fill="#050607"/></svg></span>';}
function brand(){return `<a class="brand" href="#dashboard" aria-label="DishaSetu dashboard">${iconMark()}<span>Disha<em>Setu</em></span></a>`;}
function profileName(){return state.profile?.fullName?.trim()||state.auth.email?.split('@')[0]||'Learner';}
function initial(){return profileName().trim().charAt(0).toUpperCase()||'P';}
function routeParts(){let raw=(location.hash||'').replace(/^#/,'');if(raw.startsWith('!'))raw=raw.slice(1);if(!raw)raw=state.auth.loggedIn?(state.profile?'dashboard':'onboarding'):'login';const parts=raw.split('/').filter(Boolean);return {route:parts[0]||'dashboard',args:parts.slice(1)};}
function navigate(path,replace=false){const hash='#'+path.replace(/^#/,'');if(location.hash===hash){render();return;}if(replace)history.replaceState(null,'',hash);else location.hash=hash;}
