function renderShell(route,content){const active=getActiveNav(route);const completion=getAllProgress();return `<div class="app-shell"><aside class="sidebar">${brand()}${NAV_GROUPS.map(group=>`<div class="side-label">${group.label}</div><nav class="nav-list">${group.items.map(([r,l,g])=>`<button class="nav-item ${active===r?'active':''}" type="button" data-route="${r}"><span class="nav-icon">${g}</span><span>${l}</span>${r==='roadmaps'?'<span class="nav-count">↗</span>':''}</button>`).join('')}</nav>`).join('')}<div class="sidebar-bottom"><div class="side-goal"><small>YOUR CAREER GOAL</small><b>${esc(state.profile?.career||'Choose your direction')}</b><div class="progress-track"><div class="progress-fill" style="width:${completion.percent}%"></div></div><small style="margin-top:7px">${completion.percent}% learning progress</small></div><div class="side-profile"><span class="avatar">${esc(initial())}</span><div class="user-meta"><b>${esc(profileName())}</b><small>${esc(state.profile?.college||state.auth.email||'Student account')}</small></div><button type="button" data-route="settings" aria-label="Open settings">⋯</button></div></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><div class="mobile-brand">${brand()}</div><div class="breadcrumb">Workspace <span class="muted">/</span> <b>${esc(routeTitle(route))}</b></div></div><div class="topbar-actions"><label class="search-mini" aria-label="Search roadmaps"><span>⌕</span><input id="globalSearch" placeholder="Search roadmaps…" autocomplete="off" /></label><button class="icon-button" data-route="activity" title="Learning activity" aria-label="Learning activity">▦</button><button class="icon-button" data-route="settings" title="Settings" aria-label="Settings">⚙</button><button class="btn btn-primary btn-sm" data-route="resume">Build resume <span>↗</span></button></div></header><main class="page-content"><section class="page" id="current-page">${content}</section></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navButtons(active,true)}</nav></div>`;}
function render(){const {route,args}=routeParts();if(SUPABASE_READY&&!supabaseBootComplete&&route!=='reset-password'){return;}if(!state.auth.loggedIn&&!['login','signup','reset-password'].includes(route)){navigate('login',true);return render();}if(state.auth.loggedIn&&!state.profile&&!['onboarding','login','signup','reset-password'].includes(route)){navigate('onboarding',true);return render();}if(state.auth.loggedIn&&['login','signup'].includes(route)){navigate(state.profile?'dashboard':'onboarding',true);return render();}let html='';if(route==='login'||route==='signup')html=renderAuth(route);else if(route==='reset-password')html=renderResetPassword();else if(route==='onboarding')html=renderOnboarding();else {switch(route){case'dashboard':html=renderDashboard();break;case'roadmaps':html=renderCatalog();break;case'skills':html=renderSkillsPortal();break;case'roadmap':html=renderRoadmap(args[0]||getProfileRoadmap(),Number(args[1]||0));break;case'career':html=renderCareer();break;case'projects':html=renderProjects();break;case'internships':html=renderInternships();break;case'resume':html=renderResume();break;case'analyzer':html=renderAnalyzer();break;case'activity':html=renderActivity();break;case'mentor':html=renderMentor();break;case'resources':html=renderResources();break;case'kitsw':html=renderKitsw(args);break;case'settings':html=renderSettings();break;case'profile':html=renderProfile();break;default:html=renderDashboard();}}
  $('#app').innerHTML=(route==='login'||route==='signup'||route==='onboarding')?html:renderShell(route,html);
  if(route==='resume')updateResumePreview();if(route==='mentor')scrollChatToBottom();if(route==='roadmap'){drawCurve();applyRoadmapTopicFilters();}
  document.title=`${routeTitle(route)} · DishaSetu`;
}
